	function gameStartHandler(time, mapData, gameSettings) {
		let map = "";
		for (let i = 0; i < mapData.length; i++) {
			if (i <= 100 && mapData.charAt(i) === mapData.charAt(i).toLowerCase()) {
				map += mapData.charAt(i).toUpperCase()
			} else if (i <= 100 && mapData.charAt(i) === mapData.charAt(i).toUpperCase()) {
				map += mapData.charAt(i).toLowerCase()
			} else {
				map += mapData.charAt(i)
			}
		}
		const base64 = LZString.decompressFromEncodedURIComponent(map);
		const decoded = dcodeIO.ByteBuffer.fromBase64(base64);
		map = Map.pson.decode(decoded);
		gameSettings.map = MapParser.decodeFromDatabase(gameSettings.map);
		startTS = time;
		game_ = gameSettings;
		if (lobby) {
			lobby.setGameSettings(game_);
			if (lobby.showingMapLoadWindow()) {
				lobby.closeMapLoadWindow()
			}
			if (lobby.showingMapEditor()) {
				lobby.closeMapEditor()
			}
		}
		if (gameWorld) {
			gameEnd()
		}
		const adminInputs = [];
		for (let i = 0; i < playersLeft.length; i++) {
			const playerLeft = playersLeft[i][0];
			if (adminInputs[1]) {
				if (!adminInputs[1].playersLeft) {
					adminInputs[1].playersLeft = []
				}
				adminInputs[1].playersLeft.push(playerLeft)
			} else {
				const adminInput = {
					playersLeft: [playerLeft],
					playersJoined: []
				};
				adminInputs[1] = adminInput
			}
		}
		playersLeft = [];
		const timeSinceStart = networkEngine.getTS().now() - startTS;
		gameWorld = gameWorld_;
		gameWorld_ = null;
		this.gameWorld = gameWorld;
		const worldClone = JSON.parse(JSON.stringify(game_));
		gameWorld.go(map, 0, timeSinceStart, currentId, worldClone, playerList, adminInputs);
		if (lobby) {
			lobby.hide()
		}
	}
