	function curateHandler(success, reason) {
		if (success) {
			displayStatus("* Success!", "#6033cc", true);
			curateReset()
		} else {
			switch (reason) {
				case "rate_limit":
					displayStatus("* Failed: Rate limited, please wait a few seconds then try /curateyes again", "#6033cc", true);
					break;
				case "not_logged_in":
					displayStatus("* Failed: You're a guest!", "#6033cc", true);
					curateReset();
					break;
				case "invalid_mapid":
					displayStatus("* Failed: Map issue", "#6033cc", true);
					curateReset();
					break;
				case "invalid_comment":
					displayStatus("* Failed: Comment invalid", "#6033cc", true);
					curateReset();
					break;
				case "comment_too_long":
					displayStatus("* Failed: Comment too long", "#6033cc", true);
					curateReset();
					break;
				case "invalid_dbv":
					displayStatus("* Failed: Map issue", "#6033cc", true);
					curateReset();
					break;
				case "unauthorised":
					displayStatus("* Failed: You don't have those privileges", "#6033cc", true);
					curateReset();
					break;
				case "map_private":
					displayStatus("* Failed: Map is private, it must be published", "#6033cc", true);
					curateReset();
					break;
				default:
					displayStatus("* Failed: Unknown error", "#6033cc", true);
					curateReset();
					break
			}
		}
	}
