	function fillXPBar(hasAnimation) {
		const currentLevel = game.xpToLevel(game.xp);
		const currentLevelXP = game.levelToXP(currentLevel);
		const nextLevelXP = game.levelToXP(currentLevel + 1);
		const totalXPNeeded = nextLevelXP - currentLevelXP;
		const currentProgress = game.xp - currentLevelXP;
		const nextProgress = currentProgress / totalXPNeeded;
		setXPProgress(nextProgress, hasAnimation);
		if (hasAnimation) {
			if (nextProgress == 0) {
				el_xpbartext.textContent = "Level Up"
			} else {
				el_xpbartext.textContent = "+100xp"
			}
			el_xpbartext.style.top = "10px";
			el_xpbartext.style.opacity = 0;
			const XPAnimation = anime.timeline();
			XPAnimation.add({
				targets: el_xpbartext,
				top: "-6px",
				opacity: 1,
				duration: 450,
				delay: 0,
				easing: "easeOutQuad"
			});
			XPAnimation.add({
				targets: el_xpbartext,
				top: "-20px",
				opacity: 0,
				duration: 150,
				delay: 650,
				easing: "easeOutQuad"
			})
		}
	}
