	function rowSelect() {
		if (selectedElement !== undefined) {
			replaceClass(selectedElement, "HOVERSELECTED", " HOVERUNSELECTED");
			replaceClass(selectedElement, "SELECTED", " UNSELECTED")
		}
		replaceClass(this, "HOVERUNSELECTED", " HOVERSELECTED");
		replaceClass(this, "UNSELECTED", " SELECTED");
		selectedId = this.getAttribute("data-myID");
		selectedRoom = this.cell1;
		function replaceClass(el, from, to) {
			const fromPattern = new RegExp("(?:^|\\s)" + from + "(?!\\S)", "g");
			el.className = el.className.replace(fromPattern, to)
		}
		selectedElement = this;
		game.rlc()
	}
