class Bonk1Object {
	constructor() {
		this.version = 0;
		this.x = 0;
		this.y = 0;
		this.shapeArray = [];
		this.restitution = .8;
		this.friction = 0;
		this.density = 1;
		this.angle = 0;
		this.angularVelocity = 0;
		this.isDynamic = false;
		this.xv = 0;
		this.yv = 0;
		this.linearDamping = 0;
		this.angularDamping = 0;
		this.rotates = false;
		this.rotatePivotX = 0;
		this.rotatePivotY = 0;
		this.stiffness = 0;
		this.springy = false;
		this.springyUpper = 100;
		this.springyLower = -100;
		this.springyAnchorX = 0;
		this.springyAnchorY = 0;
		this.springyForce = 1e6;
		this.path = false;
		this.pathAngle = Math.PI / 2;
		this.pathUpper = 100;
		this.pathLower = -100;
		this.pathAnchorX = 0;
		this.pathAnchorY = 0;
		this.pathMaxSpeed = 50;
		this.pathForce = 1e6
	}
	writeExternal() {}
	readExternal(view) {
		this.version = view.readShort();
		if (this.version <= 3) {
			this.x = view.readDouble();
			this.y = view.readDouble();
			this.shapeArray = [new Shape];
			this.shapeArray[0].localX = 0;
			this.shapeArray[0].localY = 0;
			this.shapeArray[0].localAngle = 0;
			this.shapeArray[0].width = view.readDouble();
			this.shapeArray[0].height = view.readDouble();
			this.restitution = view.readDouble();
			this.density = view.readDouble();
			this.friction = view.readDouble();
			this.angle = view.readDouble();
			this.angularVelocity = view.readDouble();
			this.shapeArray[0].shapeID = view.readShort();
			this.isDynamic = view.readBoolean();
			if (this.isDynamic) {
				this.xv = view.readDouble();
				this.yv = view.readDouble();
				this.linearDamping = view.readDouble();
				this.angularDamping = view.readDouble();
				this.rotates = view.readBoolean();
				if (this.rotates) {
					this.rotatePivotX = view.readDouble();
					this.rotatePivotY = view.readDouble();
					this.stiffness = view.readDouble()
				}
			}
			if (this.version >= 2) {
				this.shapeArray[0].color = view.readUint()
			} else {
				if (this.isDynamic) {
					this.shapeArray[0].color = 9159498
				} else {
					this.shapeArray[0].color = 5812595
				}
			}
			if (this.version >= 3) {
				view.readShort();
				this.shapeArray[0].death = view.readBoolean()
			} else {
				this.shapeArray[0].death = false
			}
		}
		if (this.version >= 4) {
			this.x = view.readDouble();
			this.y = view.readDouble();
			const shapeArrayLength = view.readShort();
			this.shapeArray = [];
			for (let i = 0; i < shapeArrayLength; i++) {
				this.shapeArray[i] = new Shape;
				this.shapeArray[i].localX = view.readDouble();
				this.shapeArray[i].localY = view.readDouble();
				this.shapeArray[i].width = view.readDouble();
				this.shapeArray[i].height = view.readDouble();
				this.shapeArray[i].localAngle = view.readDouble();
				this.shapeArray[i].shapeID = view.readShort();
				this.shapeArray[i].color = view.readUint();
				this.shapeArray[i].death = view.readBoolean();
				if (this.version >= 7) {
					this.shapeArray[i].noPhysics = view.readBoolean()
				}
				if (this.version == 4 && this.shapeArray[i].shapeID == 5) {
					this.shapeArray[i].height = Math.round(.866 * this.shapeArray[i].width)
				}
			}
			this.restitution = view.readDouble();
			this.density = view.readDouble();
			this.friction = view.readDouble();
			this.angle = view.readDouble();
			this.angularVelocity = view.readDouble();
			this.isDynamic = view.readBoolean();
			if (this.isDynamic) {
				this.xv = view.readDouble();
				this.yv = view.readDouble();
				this.linearDamping = view.readDouble();
				this.angularDamping = view.readDouble();
				this.rotates = view.readBoolean();
				if (this.rotates) {
					this.rotatePivotX = view.readDouble();
					this.rotatePivotY = view.readDouble();
					this.stiffness = view.readDouble()
				}
				if (this.version >= 6) {
					this.springy = view.readBoolean();
					if (this.springy) {
						this.springyUpper = view.readDouble();
						this.springyLower = -this.springyUpper;
						this.springyForce = view.readDouble();
						this.springyAnchorX = view.readDouble();
						this.springyAnchorY = view.readDouble()
					}
					this.path = view.readBoolean();
					if (this.path) {
						this.pathAngle = view.readDouble();
						this.pathUpper = view.readDouble();
						this.pathLower = -this.pathUpper;
						this.pathMaxSpeed = view.readDouble();
						this.pathForce = view.readDouble();
						this.pathAnchorX = view.readDouble();
						this.pathAnchorY = view.readDouble()
					}
				}
			}
		}
	}
}
