class Bonk1CaptureZone {
	constructor() {
		this.version = 0;
		this.radius = 0;
		this.x = 0;
		this.y = 0;
		this.captureLimit = 0;
		this.ownerID = 0;
		this.framesToDetonate = 0
	}
	writeExternal() {}
	readExternal(view) {
		for (let i = 0; i < 8; i++) {
			const f239v0 = view.readByte();
			if (f239v0 == BonkView.T_INT) {
				this[view.bodgeCaptureZoneDataIdentifierArray[i]] = view.readInt29()
			} else if (f239v0 == BonkView.T_DOUBLE) {
				this[view.bodgeCaptureZoneDataIdentifierArray[i]] = view.readDouble()
			}
		}
	}
	readAnonymous(view) {
		view.bodgeCaptureZoneDataIdentifierArray = [];
		for (let i = 0; i < 8; i++) {
			const _l = view.readByte();
			const length = (_l - 1) / 2;
			const newArr = new Uint8Array(length);
			for (let j = 0; j < length; j++) {
				newArr[j] = view.readByte()
			}
			const decoded = BonkView.textDec.decode(newArr);
			view.bodgeCaptureZoneDataIdentifierArray.push(decoded)
		}
		this.readExternal(view)
	}
}
