	let winningTeam = map.lscr;
	let isGoal = false;
	if (map.ftu == -1 && map.fte == -1) {
		const ballX = ball.body.GetPosition().x;
		if (ballX < (map.borderThickness + map.borderThicknessXInner) / map.ppm) {
			scores[2]++;
			winningTeam = 2;
			isGoal = true;
			FootballPhysics.soundsThisStep.push({
				i: "footGoal",
				v: 1,
				p: "l",
				f: 5
			})
		}
		if (ballX > (730 - map.borderThickness - map.borderThicknessXInner) / map.ppm) {
			scores[3]++;
			winningTeam = 3;
			isGoal = true;
			FootballPhysics.soundsThisStep.push({
				i: "footGoal",
				v: 1,
				p: "r",
				f: 5
			})
		}
	}
