	newStep.scores = scores;
	newStep.goalHeight = map.goalHeight;
	newStep.borderThickness = map.borderThickness;
	newStep.borderThicknessXInner = map.borderThicknessXInner;
	newStep.borderThicknessYInner = map.borderThicknessYInner;
	newStep.ppm = map.ppm;
	newStep.lscr = winningTeam;
