class Ball {
	constructor(world, pos) {
		this.world = world;
		const ballBodyDef = new b2BodyDef;
		ballBodyDef.type = b2Body.b2_dynamicBody;
		ballBodyDef.position.Set(pos.x, pos.y);
		const ballBody = world.CreateBody(ballBodyDef);
		const ballShape = new b2CircleShape(.7);
		const ballFixture = new b2FixtureDef;
		ballFixture.shape = ballShape;
		ballFixture.restitution = .4;
		ballFixture.density = .6 / (Math.PI * .7 * .7);
		ballFixture.friction = 0;
		ballFixture.filter.categoryBits = 4;
		ballBody.CreateFixture(ballFixture);
		ballBody.SetLinearVelocity(new b2Vec2(pos.xv, pos.yv));
		const ballData = {};
		ballData.type = "ball";
		ballData.ballReference = this;
		ballBody.SetUserData(ballData);
		ballBody.SetFixedRotation(true);
		ballBody.SetLinearDamping(.6);
		ballBody.SetBullet(true);
		this.body = ballBody
	}
	output() {
		let ballInfo = {};
		ballInfo = {};
		ballInfo.x = this.body.GetPosition().x;
		ballInfo.y = this.body.GetPosition().y;
		ballInfo.xv = this.body.GetLinearVelocity().x;
		ballInfo.yv = this.body.GetLinearVelocity().y;
		return ballInfo
	}
	destroy() {
		this.world.DestroyBody(this.body);
		this.world = null
	}
}
class FootballPlayer {
	constructor(world, player, ppm) {
		this.world = world;
		this.radius = 1;
		this.ppm = ppm;
		const playerBodyDef = new b2BodyDef;
		playerBodyDef.type = b2Body.b2_dynamicBody;
		playerBodyDef.position.Set(player.x, player.y);
		playerBodyDef.fixedRotation = true;
		playerBodyDef.linearDamping = 2.4;
		playerBodyDef.linearVelocity.x = player.xv;
		playerBodyDef.linearVelocity.y = player.yv;
		playerBodyDef.bullet = true;
		const playerBody = world.CreateBody(playerBodyDef);
		const playerShape = new b2CircleShape;
		playerShape.SetRadius(this.radius);
		const playerFixture = new b2FixtureDef;
		playerFixture.shape = playerShape;
		playerFixture.friction = 0;
		playerFixture.restitution = .4;
		playerFixture.density = 1.05 / (Math.PI * this.radius * this.radius);
		playerFixture.filter.categoryBits = 2;
		playerBody.CreateFixture(playerFixture);
		const playerData = {};
		playerData.type = "disc";
		playerData.discReference = this;
		playerBody.SetUserData(playerData);
		this.body = playerBody;
		this.kickReady = player.kickReady;
		this.inputState = player
	}
	applyInputs(inputs) {
		const forceVector = new b2Vec2(0, 0);
		const speed = 32;
		if (inputs.left) {
			forceVector.x = -speed
		} else if (inputs.right) {
			forceVector.x = speed
		}
		if (inputs.up) {
			forceVector.y = -speed
		} else if (inputs.down) {
			forceVector.y = speed
		}
		if (inputs.action) {
			forceVector.Multiply(.7)
		}
		if (inputs.action2) {
			forceVector.x = 0;
			forceVector.y = 0
		}
		this.body.ApplyForce(forceVector, this.body.GetWorldCenter())
	}
	doKick(inputs, ball) {
		if (inputs.action && this.kickReady) {
			const ballPosition = this.body.GetPosition().Copy();
			ballPosition.Subtract(ball.GetPosition());
			if (Math.abs(ballPosition.Length()) < .7 + this.radius + .6) {
				let ballImpulse = ballPosition.Copy();
				ballImpulse = ballImpulse.GetNegative();
				const ballPositionLength = ballPosition.Length();
				const mod = ballPositionLength / 15;
				ballImpulse.x = ballImpulse.x / mod;
				ballImpulse.y = ballImpulse.y / mod;
				ball.ApplyImpulse(ballImpulse, ball.GetPosition());
				this.kickReady = false;
				FootballPhysics.soundsThisStep.push({
					i: "footKick",
					v: 1,
					f: 10
				})
			}
		}
		if (!inputs.action) {
			this.kickReady = true
		}
	}
	clampToPitch() {
		const ballPosition = this.body.GetPosition();
		if (ballPosition.x < 0 + this.radius) {
			ballPosition.x = 0 + this.radius;
			this.body.GetLinearVelocity().x = 0
		}
		if (ballPosition.x > 730 / this.ppm - this.radius) {
			ballPosition.x = 730 / this.ppm - this.radius;
			this.body.GetLinearVelocity().x = 0
		}
		if (ballPosition.y < 0 + this.radius) {
			ballPosition.y = 0 + this.radius;
			this.body.GetLinearVelocity().y = 0
		}
		if (ballPosition.y > 500 / this.ppm - this.radius) {
			ballPosition.y = 500 / this.ppm - this.radius;
			this.body.GetLinearVelocity().y = 0
		}
	}
	output() {
		const output = {};
		output.x = this.body.GetPosition().x;
		output.y = this.body.GetPosition().y;
		output.xv = this.body.GetLinearVelocity().x;
		output.yv = this.body.GetLinearVelocity().y;
		output.team = this.inputState.team;
		output.kickReady = this.kickReady;
		return output
	}
	destroy() {
		this.world.DestroyBody(this.body);
		this.world = null;
		this.inputState = null
	}
}
