	updateParticles() {
		let timeSinceLastAnim = Date.now() - this.lastAnimationTime;
		let multiplier = 1;
		if (this.lastAnimationTime == -1) {
			timeSinceLastAnim = .016666666666666666
		}
		this.lastAnimationTime = Date.now();
		multiplier = timeSinceLastAnim / (1e3 / 60);
		for (let i = 0; i < this.particles.length; i++) {
			const particle = this.particles[i];
			if (particle.graphics.scale.x <= 0) {
				this.container.removeChild(particle.graphics);
				particle.graphics.destroy({
					children: true,
					texture: false,
					baseTexture: false
				});
				this.particles.splice(i, 1);
				i--;
				continue
			}
			particle.graphics.x += particle.xv * 2 * multiplier * this.scaleRatio;
			particle.graphics.y += particle.yv * 2 * multiplier * this.scaleRatio;
			particle.yv += particle.gravity * multiplier;
			particle.xv *= 1 - .02 * multiplier;
			particle.yv *= 1 - .01 * multiplier;
			particle.graphics.rotation = Math.atan2(particle.yv, particle.xv);
			particle.graphics.alpha = particle.alpha;
			particle.graphics.width -= particle.shrinkPerFrame * multiplier * 7;
			particle.graphics.height -= particle.shrinkPerFrame * multiplier * 7
		}
	}
