	function showGuestColorPicker(callback, element, topOffset) {
		if (guestColorPicker) {
			guestColorPicker.parentNode.removeChild(guestColorPicker);
			guestColorPicker = null;
			return
		}
		guestColorPicker = document.createElement("div");
		guestColorPicker.classList.add("sm_pickerContainer");
		guestColorPicker.classList.add("windowShadow");
		guestColorPicker.style.top = topOffset + "px";
		for (let i = 0; i < game.colors.length; i++) {
			const pickerColorContainer = document.createElement("div");
			pickerColorContainer.classList.add("sm_pickerColorContainer");
			guestColorPicker.appendChild(pickerColorContainer);
			const pickerColor = document.createElement("div");
			pickerColor.classList.add("sm_pickerColorInner");
			pickerColor.style.backgroundColor = game.numToHex(game.colors[i]);
			pickerColorContainer.appendChild(pickerColor);
			pickerColor.colorVal = game.colors[i];
			pickerColor.onclick = function() {
				game.avatar.bc = this.colorVal;
				callback(this.colorVal);
				anime({
					targets: guestColorPicker,
					left: "-270px",
					opacity: 0,
					autoplay: true,
					duration: 120,
					easing: "easeInCubic",
					complete: function() {
						guestColorPicker.parentNode.removeChild(guestColorPicker);
						guestColorPicker = null
					}
				})
			}
		}
		element.appendChild(guestColorPicker);
		guestColorPicker.style.left = "-270px";
		guestColorPicker.style.opacity = "0";
		anime({
			targets: guestColorPicker,
			left: "-290px",
			opacity: 1,
			autoplay: true,
			duration: 120,
			easing: "easeInOutCubic"
		})
	}
