	function setFriendRequestText(req) {
		el_friendsSendWindow_name.style.visibility = "hidden";
		el_friendsSendWindow_label.style.visibility = "hidden";
		el_friendsSendWindow_responselabel.style.visibility = "inherit";
		if (req.r == "fail") {
			if (req.e == "ratelimited") {
				el_friendsSendWindow_responselabel.textContent = "You're doing that too much!"
			} else if (req.e == "username_invalid") {
				el_friendsSendWindow_responselabel.textContent = "That name is invalid"
			} else if (req.e == "username_not_found") {
				el_friendsSendWindow_responselabel.textContent = "No accounts found with that name"
			} else if (req.e == "cant_friend_self") {
				el_friendsSendWindow_responselabel.textContent = "Can't friend yourself!"
			} else if (req.e == "already_friends") {
				el_friendsSendWindow_responselabel.textContent = "You're already friends!"
			} else if (req.e == "already_sent_request") {
				el_friendsSendWindow_responselabel.textContent = "You've already sent them a friend request"
			} else {
				el_friendsSendWindow_responselabel.textContent = req.e
			}
			el_friendsSendWindow_send.childNodes[1].textContent = "Try Again"
		} else {
			if (req.r == "send_success") {
				el_friendsSendWindow_responselabel.textContent = "Friend request sent successfully!"
			}
			if (req.r == "accept_success") {
				el_friendsSendWindow_responselabel.textContent = "They sent a request too, so you are now friends!"
			}
			el_friendsSendWindow_send.childNodes[1].textContent = "Send Another"
		}
		el_friendsSendWindow_send.onclick = f498
	}
	this.startMusic = function() {
		if (music) {
			music.off("fade", f526);
			music.off("end", f535);
			music.stop()
		}
		if (++musicCounter > 1) {
			musicCounter = 0
		}
		let musicURL = "";
		if (game.isItChristmas()) {
			if (musicCounter == 0) {
				musicURL = "sound/128_blc.mp3"
			} else {
				musicURL = "sound/128_mcg.mp3"
			}
		} else {
			if (musicCounter == 0) {
				musicURL = "sound/128_wmb.mp3"
			} else {
				musicURL = "sound/128_vdp.mp3"
			}
		}
		music = new Howl({
			src: [musicURL],
			volume: .4,
			loop: false
		});
		music.on("end", f535);
		music.play()
	};
	this.stopMusic = function() {
		if (music) {
			music.fade(music._volume, 0, 2e3);
			music.on("fade", f526)
		}
	};
