class SnowRenderer {
	constructor(scale) {
		this.displayObject = new PIXI.Container;
		this.snows = [];
		this.lastRenderTime = Date.now();
		if (game.isItChristmas()) {
			const dayOfYear = game.getDayOfYear();
			const rand1 = this.seededRand(dayOfYear);
			const rand2 = this.seededRand(dayOfYear + 50);
			const rand3 = this.seededRand(dayOfYear + 150);
			this.xLimit = 730 * scale;
			this.yLimit = 500 * scale;
			let snowQuantityMultiplier = 110;
			if (game.customControls.quality == 2) {
				snowQuantityMultiplier = 60
			} else if (game.customControls.quality == 1) {
				snowQuantityMultiplier = 20
			}
			this.snowQuantity = Math.round(10 + rand1 * snowQuantityMultiplier);
			this.todaysBaseWindAmount = -.6 + rand2 * 1.2;
			this.todaysBaseGravAmount = .5 + rand3 * .4;
			this.build()
		}
	}
	seededRand(number) {
		number *= 1e5;
		number = number * number % (7247 * 7823);
		return number / (7247 * 7823)
	}
	build() {
		for (let i = 0; i < this.snowQuantity; i++) {
			const randomX = Math.random() * this.xLimit;
			const randomY = Math.random() * this.yLimit;
			const snowflake = new PIXI.Sprite(PIXI.Texture.WHITE);
			snowflake.width = 3;
			snowflake.height = 3;
			this.displayObject.addChild(snowflake);
			snowflake.x = randomX;
			snowflake.y = randomY;
			this.snows.push(snowflake)
		}
	}
	render() {
		if (game.nosnow) {
			return
		}
		const deltaTime = Date.now() - this.lastRenderTime;
		const modifier = deltaTime / (1e3 / 120);
		this.snows.forEach((snowflake, index) => {
			const xMod = -.1 + index / this.snowQuantity * .2;
			snowflake.x += (this.todaysBaseWindAmount + xMod) * modifier;
			snowflake.y += (this.todaysBaseGravAmount + Math.random() * .2) * modifier;
			snowflake.angle += 1 * modifier;
			if (this.todaysBaseWindAmount > 0) {
				if (snowflake.x > this.xLimit) {
					snowflake.x -= this.xLimit
				}
			}
			if (this.todaysBaseWindAmount < 0) {
				if (snowflake.x < 0) {
					snowflake.x += this.xLimit
				}
			}
			if (snowflake.y > this.yLimit) {
				snowflake.y -= this.yLimit
			}
		});
		this.lastRenderTime = Date.now()
	}
	destroy() {
		this.snows.forEach(f617a0 => {
			f617a0.destroy()
		});
		this.snow = []
	}
}
class Arrow {
	constructor(id, player, playerId, team, ratio, isDeath, renderer) {
		if (!renderer.deathArrowTexture) {
			this.createDeathArrowTexture(renderer)
		}
		if (isDeath) {
			this.graphic = new PIXI.Sprite(renderer.deathArrowTexture)
		} else {
			this.graphic = new PIXI.Sprite(PIXI.Texture.WHITE)
		}
		this.graphic.width = 1 * ratio;
		this.graphic.height = .5 * ratio;
		this.graphic.anchor.x = .5;
		this.graphic.anchor.y = .5;
		this.arrowID = id;
		this.ppm = ratio;
		this.ownerID = playerId;
		if (player && player.avatar) {
			let bgColor = player.avatar.bc;
			if (bgColor > 16777215) {
				bgColor = 16777215
			}
			this.graphic.tint = game.teamify(bgColor, team)
		}
	}
	createDeathArrowTexture(f619a0) {
		const f619v2 = new PIXI.Graphics;
		const f619v3 = 1 * 40;
		const f619v4 = .5 * 40;
		f619v2.beginFill(16777215);
		f619v2.lineStyle({
			width: 6,
			color: 0
		});
		f619v2.drawRect(0, 0, f619v3, f619v4);
		f619v2.endFill();
		f619a0.deathArrowTexture = f619a0.generateTexture(f619v2)
	}
	build() {}
	move(prevStep, currentStep, t) {
		const prevX = prevStep.projectiles[this.arrowID].x * this.ppm;
		const prevY = prevStep.projectiles[this.arrowID].y * this.ppm;
		const currentX = currentStep.projectiles[this.arrowID].x * this.ppm;
		const currentY = currentStep.projectiles[this.arrowID].y * this.ppm;
		const prevAngle = prevStep.projectiles[this.arrowID].a;
		const currentAngle = currentStep.projectiles[this.arrowID].a;
		this.graphic.x = (1 - t) * prevX + t * currentX;
		this.graphic.y = (1 - t) * prevY + t * currentY;
		const cosPrevAngle = Math.cos(prevAngle);
		const sinPrevAngle = Math.sin(prevAngle);
		const cosCurrentAngle = Math.cos(currentAngle);
		const sinCurrentAngle = Math.sin(currentAngle);
		const cosLerp = (1 - t) * cosPrevAngle + t * cosCurrentAngle;
		const sinLerp = (1 - t) * sinPrevAngle + t * sinCurrentAngle;
		this.graphic.rotation = Math.atan2(sinLerp, cosLerp)
	}
	destroy() {
		this.graphic.destroy(false)
	}
}
