	function decodeUrlParams(params) {
		let url = "www.bleh.com/?" + params;
		if (!url) {
			url = location.href
		}
		const questionMarkPos = url.indexOf("?");
		let poundPos = url.indexOf("#");
		if (poundPos == -1 && questionMarkPos == -1) {
			return {}
		}
		if (poundPos == -1) {
			poundPos = url.length
		}
		const urlParams = questionMarkPos == -1 || poundPos == questionMarkPos + 1 ? url.substring(poundPos) : url.substring(questionMarkPos + 1, poundPos);
		const mapList = {};
		urlParams.split("&").forEach(function(param) {
			if (!param) {
				return
			}
			param = param.split("+").join(" ");
			const equalPos = param.indexOf("=");
			let paramName = equalPos > -1 ? param.substr(0, equalPos) : param;
			let paramValue = "";
			try {
				paramValue = equalPos > -1 ? decodeURIComponent(param.substr(equalPos + 1)) : ""
			} catch (err) {}
			const openingBracketPos = paramName.indexOf("[");
			if (openingBracketPos == -1) {
				mapList[decodeURIComponent(paramName)] = paramValue
			} else {
				const closingBracketPos = paramName.indexOf("]", openingBracketPos);
				const decodedKey = decodeURIComponent(paramName.substring(openingBracketPos + 1, closingBracketPos));
				paramName = decodeURIComponent(paramName.substring(0, openingBracketPos));
				if (!mapList[paramName]) {
					mapList[paramName] = []
				}
				if (!decodedKey) {
					mapList[paramName].push(paramValue)
				} else {
					mapList[paramName][decodedKey] = paramValue
				}
			}
		});
		return mapList
	}
