	function addUpvoteRatioAndAmount(div, upvotes, downvotes, picks) {
		const el = document.createElement("div");
		if (picks) {
			el.classList.add("maploadwindowbarcontainer_picks")
		} else {
			el.classList.add("maploadwindowbarcontainer")
		}
		if (upvotes > 0 || downvotes > 0) {
			const filledDiv = document.createElement("div");
			filledDiv.classList.add("maploadwindowbarcontainer_left");
			const unfilledDiv = document.createElement("div");
			unfilledDiv.classList.add("maploadwindowbarcontainer_right");
			let upvoteRatio = upvotes / (upvotes + downvotes);
			const tmp = upvoteRatio + .15;
			upvoteRatio *= tmp * tmp;
			upvoteRatio = Math.min(1, upvoteRatio);
			filledDiv.style.width = Math.ceil(upvoteRatio * 100) + "%";
			unfilledDiv.style.width = (1 - upvoteRatio) * 100 + "%";
			el.appendChild(filledDiv);
			el.appendChild(unfilledDiv)
		} else {
			const novotesDiv = document.createElement("div");
			novotesDiv.classList.add("maploadwindowbarcontainer_novotes");
			el.appendChild(novotesDiv)
		}
		const voteAmountContainer = document.createElement("span");
		voteAmountContainer.classList.add("maploadwindowtext");
		if (picks) {
			voteAmountContainer.classList.add("maploadwindowtextvotediff_picks")
		} else {
			voteAmountContainer.classList.add("maploadwindowtextvotediff")
		}
		let _upvotes = upvotes;
		if (!isNaN(_upvotes)) {
			if (_upvotes > 1e5) {
				_upvotes /= 1e3;
				_upvotes = Math.floor(_upvotes);
				_upvotes = _upvotes + "k"
			} else if (_upvotes > 1e3) {
				_upvotes /= 100;
				_upvotes = Math.floor(_upvotes);
				_upvotes /= 10;
				_upvotes = _upvotes + "k"
			}
			const contents = "+" + _upvotes + " ";
			voteAmountContainer.textContent = contents
		}
		let _downvotes = downvotes;
		if (!isNaN(_downvotes)) {
			if (_downvotes > 1e5) {
				_downvotes /= 1e3;
				_downvotes = Math.floor(_downvotes);
				_downvotes = _downvotes + "k"
			} else if (_downvotes > 1e3) {
				_downvotes /= 100;
				_downvotes = Math.floor(_downvotes);
				_downvotes /= 10;
				_downvotes = _downvotes + "k"
			}
			const contents = "-" + _downvotes;
			voteAmountContainer.textContent += contents
		}
		div.appendChild(voteAmountContainer);
		div.appendChild(el)
	}
