	function addHot(e, offset) {
		hideStatusText();
		if (e.maps.length == 0 && offset == 0) {
			mapLoadStatus("No Maps")
		}
		for (let i = offset * 32; i < Math.min(e.maps.length, (offset + 1) * 32); i++) {
			try {
				const mergedMap = MapParser.mergeIntoNewMap(MapParser.decodeFromDatabase(e.maps[i].leveldata));
				mergedMap.m.n = e.maps[i].name;
				mergedMap.m.a = e.maps[i].authorname;
				mergedMap.m.dbid = parseInt(e.maps[i].id);
				mergedMap.m.date = e.maps[i].publisheddate;
				mergedMap.m.dbv = 2;
				mergedMap.m.vu = e.maps[i].vu;
				mergedMap.m.vd = e.maps[i].vd;
				mergedMap.m.pub = mergedMap.m.a == game.userName ? true : false;
				const container = document.createElement("div");
				container.classList.add("maploadwindowmapdiv");
				mapDivs.push({
					map: mergedMap,
					div: container
				});
				const mapTextAuthor = document.createElement("span");
				mapTextAuthor.classList.add("maploadwindowtext");
				mapTextAuthor.classList.add("maploadwindowtextname");
				mapTextAuthor.textContent = mergedMap.m.n;
				const f695v3 = document.createElement("span");
				f695v3.classList.add("maploadwindowtext");
				f695v3.classList.add("maploadwindowtextauthor");
				f695v3.textContent = mergedMap.m.a;
				const mapTextMode = document.createElement("span");
				mapTextMode.classList.add("maploadwindowtext");
				mapTextMode.classList.add("maploadwindowtextmode");
				let modeName = "Any Mode";
				if (Game.modes[mergedMap.m.mo] && Game.modes[mergedMap.m.mo].editorCanTarget) {
					modeName = Game.modes[mergedMap.m.mo].lobbyName
				}
				mapTextMode.textContent = modeName;
				container.appendChild(mapTextMode);
				const mapTextAge = document.createElement("span");
				mapTextAge.classList.add("maploadwindowtext");
				mapTextAge.classList.add("maploadwindowtextage");
				let formattedDate = "";
				formattedDate = moment(mergedMap.m.date, "YYYY-MM-DD HH:mm:ss").fromNow();
				mapTextAge.textContent = formattedDate;
				addUpvoteRatioAndAmount(container, mergedMap.m.vu, mergedMap.m.vd);
				container.appendChild(mapTextAuthor);
				container.appendChild(f695v3);
				container.appendChild(mapTextAge);
				el_maploadwindowmapscontainer.appendChild(container);
				container.map = mergedMap;
				container.onclick = function() {
					mapListEvent("mapChosen", this.map);
					self.hide();
					game.bcs()
				};
				container.onmouseenter = playListRowSound
			} catch (err) {}
		}
	}
