	function mapListEvent(...args) {
		const eventName = args.shift();
		for (let i = 0; i < mapListEventListeners.length; i++) {
			if (mapListEventListeners[i].eventName == eventName) {
				mapListEventListeners[i].callback(...args)
			}
		}
	}
