	this.updatePings = function() {
		for (let i = 0; i < playerList.length; i++) {
			if (playerList[i] && playerPings[i] && f734v13[i]) {
				const playerPing = playerList[i].ping;
				const isHost = networkEngine.hostID == i;
				const isTabbed = playerList[i].tabbed;
				let imagePingType = 1;
				if (playerPing <= 100) {
					imagePingType = 5
				}
				if (playerPing > 100 && playerPing <= 200) {
					imagePingType = 4
				}
				if (playerPing > 200 && playerPing <= 300) {
					imagePingType = 3
				}
				if (playerPing > 300 && playerPing <= 400) {
					imagePingType = 2
				}
				if (playerPing > 400) {
					imagePingType = 1
				}
				if (isTabbed) {
					imagePingType = "tab"
				}
				if (playerPings[i].lastSet != imagePingType) {
					playerPings[i].img.src = "graphics/ping_" + imagePingType + ".png";
					playerPings[i].lastSet = imagePingType
				}
				if (imagePingType == "tab") {
					playerPings[i].text.textContent = "Tab"
				} else if (playerPing === undefined) {
					playerPings[i].text.textContent = "-ms"
				} else {
					playerPings[i].text.textContent = playerPing + "ms"
				}
				if (isHost) {
					if (f734v13[i].lastSet != imagePingType) {
						f734v13[i].src = "graphics/host_" + imagePingType + ".png";
						f734v13[i].lastSet = imagePingType
					}
				} else {
					if (f734v13[i].lastSet != 0) {
						f734v13[i].src = "graphics/host_0.png";
						f734v13[i].lastSet = 0
					}
				}
			}
		}
	};
