function EnterFrameDispatcher() {
	this.callbacks = [];
	const self = this;
	this.subscribe = function(priority, handler) {
		for (let i = 0; i < self.callbacks.length; i++) {
			if (self.callbacks[i].handler == handler) {
				return
			}
		}
		self.callbacks.push({
			handler: handler,
			priority: priority
		})
	};
	this.unsubscribe = function(callback) {
		if (typeof callback != "function") {
			throw new Error("Trying to unsubscribe a non function")
		}
		for (let i = 0; i < self.callbacks.length; i++) {
			if (self.callbacks[i].handler == callback) {
				self.callbacks.splice(i, 1);
				break
			}
		}
	};
	this.dispatch = function() {
		for (let i = 10; i >= 0; i--) {
			for (let j = 0; j < self.callbacks.length; j++) {
				if (self.callbacks[j].priority == i) {
					self.callbacks[j].handler.apply()
				}
			}
		}
	}
}
