	function historyPush() {
		while (historyIndex > 0) {
			history.shift();
			historyIndex--
		}
		history.unshift(JSON.stringify(world));
		while (history.length > 20) {
			history.pop()
		}
		historyButtonUpdate()
	}
	function historyUndo() {
		if (!history[historyIndex + 1]) {
			return
		}
		historyIndex++;
		const state = history[historyIndex];
		world = JSON.parse(state);
		f893()
	}
