	function cloneFixture(cloneInfo) {
		const cloneTarget = cloneInfo.target;
		if (!world.physics.bodies[cloneTarget]) {
			return
		}
		const origZIndex = world.physics.bro.indexOf(cloneTarget);
		const orig = world.physics.bodies[cloneTarget];
		const origClone = JSON.parse(JSON.stringify(orig));
		world.physics.bodies.push(origClone);
		const cloneIndex = world.physics.bodies.length - 1;
		world.physics.bro.splice(origZIndex, 0, cloneIndex);
		for (let i = 0; i < origClone.fx.length; i++) {
			const fixture = origClone.fx[i];
			const fx = world.physics.fixtures[fixture];
			const fxClone = JSON.parse(JSON.stringify(fx));
			world.physics.fixtures.push(fxClone);
			const fxCloneIndex = world.physics.fixtures.length - 1;
			const fxShapeIndex = fx.sh;
			const shape = world.physics.shapes[fxShapeIndex];
			const shapeClone = JSON.parse(JSON.stringify(shape));
			world.physics.shapes.push(shapeClone);
			const f896v15 = world.physics.shapes.length - 1;
			fxClone.sh = f896v15;
			origClone.fx[i] = fxCloneIndex;
			if (shapeClone.type == "ci") {
				if (cloneInfo.mirrorX) {
					shapeClone.c[0] = -shapeClone.c[0]
				}
				if (cloneInfo.mirrorY) {
					shapeClone.c[1] = -shapeClone.c[1]
				}
			}
			if (shapeClone.type == "bx") {
				if (cloneInfo.mirrorX) {
					shapeClone.c[0] = -shapeClone.c[0];
					shapeClone.a = -shapeClone.a
				}
				if (cloneInfo.mirrorY) {
					shapeClone.c[1] = -shapeClone.c[1];
					shapeClone.a = -shapeClone.a
				}
			}
			if (shapeClone.type == "po") {
				let f896v16 = false;
				if (cloneInfo.mirrorX) {
					shapeClone.c[0] = -shapeClone.c[0];
					for (let j = 0; j < shapeClone.v.length; j++) {
						shapeClone.v[j][0] = -shapeClone.v[j][0]
					}
					shapeClone.a = -shapeClone.a;
					f896v16 = true
				}
				if (cloneInfo.mirrorY) {
					shapeClone.c[1] = -shapeClone.c[1];
					for (let j = 0; j < shapeClone.v.length; j++) {
						shapeClone.v[j][1] = -shapeClone.v[j][1]
					}
					shapeClone.a = -shapeClone.a;
					f896v16 = true
				}
				if (f896v16) {
					f922(shapeClone)
				}
			}
		}
		if (cloneInfo.invertXPos) {
			origClone.p[0] = -origClone.p[0]
		}
		if (cloneInfo.invertYPos) {
			origClone.p[1] = -origClone.p[1]
		}
		if (cloneInfo.mirrorX) {
			origClone.a = -origClone.a
		}
		if (cloneInfo.mirrorY) {
			origClone.a = -origClone.a
		}
		if (cloneInfo.rotate != 0) {
			origClone.a += cloneInfo.rotate * (Math.PI / 180)
		}
		for (let i = 0; i < world.physics.joints.length; i++) {
			const joint = world.physics.joints[i];
			if (joint.ba == cloneTarget) {
				const jointClone = JSON.parse(JSON.stringify(joint));
				jointClone.ba = cloneIndex;
				world.physics.joints.push(jointClone);
				if (jointClone.type == "d") {
					const f896v20 = origClone.p[0] - orig.p[0];
					const f896v23 = origClone.p[1] - orig.p[1];
					jointClone.ab[0] += f896v20;
					jointClone.ab[1] += f896v23;
					if (cloneInfo.mirrorX) {}
					if (cloneInfo.mirrorY) {}
				}
				if (jointClone.type == "rv") {
					if (cloneInfo.mirrorX) {
						jointClone.aa[0] = -jointClone.aa[0]
					}
					if (cloneInfo.mirrorY) {
						jointClone.aa[1] = -jointClone.aa[1]
					}
				}
				if (jointClone.type == "lpj") {
					if (cloneInfo.mirrorX) {
						jointClone.pa = -jointClone.pa
					}
					if (cloneInfo.mirrorY) {
						jointClone.pa = -jointClone.pa
					}
				}
			}
		}
	}
