	function getPointCoordinates(e, f899a1) {
		const f899v0 = e.target.getBoundingClientRect();
		const f899v1 = e.clientX - f899v0.left;
		const f899v2 = e.clientY - f899v0.top;
		const f899v3 = f899v1 / f899v0.width;
		const f899v4 = f899v2 / f899v0.height;
		const f899v5 = canvasGraphics.screenRatioToPhysicsCoordinate(f899v3, f899v4);
		f899v5.x = Math.round(f899v5.x);
		f899v5.y = Math.round(f899v5.y);
		if (!f899a1 && gridOn) {
			f899v5.x = Math.round(f899v5.x / world.s.gd) * world.s.gd;
			f899v5.y = Math.round(f899v5.y / world.s.gd) * world.s.gd
		}
		return f899v5
	}
