	function getPhysicsShapesAmount() {
		let shapeCount = 0;
		for (let i = 0; i < world.physics.fixtures.length; i++) {
			if (world.physics.fixtures[i].np == false) {
				shapeCount++
			}
		}
		let noSpawnWarning = "";
		if (world.spawns.length == 0) {
			noSpawnWarning = " (Warning: No spawn points)"
		}
		if (shapeCount <= 10) {
			el_mapeditor_midbox_shapecount.textContent = shapeCount + " physics shapes: no lag" + noSpawnWarning
		} else if (shapeCount <= 30) {
			el_mapeditor_midbox_shapecount.textContent = shapeCount + " physics shapes: map may be a bit laggy" + noSpawnWarning
		} else if (shapeCount <= 50) {
			el_mapeditor_midbox_shapecount.textContent = shapeCount + " physics shapes: probably laggy for some players" + noSpawnWarning
		} else if (shapeCount <= 80) {
			el_mapeditor_midbox_shapecount.textContent = shapeCount + " physics shapes: laggy for most players" + noSpawnWarning
		} else {
			el_mapeditor_midbox_shapecount.textContent = shapeCount + " physics shapes: this map is probably unplayable" + noSpawnWarning
		}
	}
