	function moveBody() {
		if (bodyId == -1) {
			return
		}
		const bodyIndex = world.physics.bro.indexOf(bodyId);
		if (bodyIndex == -1) {
			return
		}
		if (this == el_mapeditor_leftbox_upbutton) {
			if (world.physics.bro[bodyIndex - 1] != undefined) {
				const prevBody = world.physics.bro[bodyIndex - 1];
				world.physics.bro[bodyIndex - 1] = world.physics.bro[bodyIndex];
				world.physics.bro[bodyIndex] = prevBody
			}
		} else if (this == el_mapeditor_leftbox_downbutton) {
			if (world.physics.bro[bodyIndex + 1] != undefined) {
				const nextBody = world.physics.bro[bodyIndex + 1];
				world.physics.bro[bodyIndex + 1] = world.physics.bro[bodyIndex];
				world.physics.bro[bodyIndex] = nextBody
			}
		}
		rebuildList();
		updateState(true)
	}
