	function createNewShape(type, cx, cy) {
		let shape = null;
		if (type == "ci") {
			shape = MapParser.getNewCircleShape();
			if (cx != null) {
				shape.c[0] = cx;
				shape.c[1] = cy
			}
		}
		if (type == "bx") {
			shape = MapParser.getNewBoxShape();
			if (cx != null) {
				shape.c[0] = cx;
				shape.c[1] = cy
			}
		}
		if (type == "po") {
			shape = MapParser.getNewPolyShape()
		}
		const shapeIndex = world.physics.shapes.length;
		world.physics.shapes[shapeIndex] = shape;
		const shapeFixture = MapParser.getNewFixture(shapeIndex);
		world.physics.fixtures[shapeIndex] = shapeFixture;
		shapeFixture.n = "Unnamed Shape";
		shapeFixture.fr = null;
		shapeFixture.re = null;
		shapeFixture.de = null;
		shapeFixture.f = defaultColor;
		return shapeIndex
	}
