	function performStep(stepDuration) {
		const nothing = getNothing(currentStep);
		const step = physics.step(steps[currentStep], nothing, f845v29[currentStep], stepDuration, gameSettings, 1);
		currentStep++;
		steps[currentStep] = step;
		if (currentStep >= 60) {
			steps[currentStep - 60] = null
		}
	}
