	function f950(f950a0, f950a1) {
		let f950v0 = null;
		if (f950a1 == "rotating") {
			f950v0 = MapParser.getNewRevoluteJoint(f950a0, -1);
			f950v0.d.cc = false
		}
		if (f950a1 == "lpj") {
			f950v0 = MapParser.getNewLPJJoint(f950a0, -1);
			f950v0.plen = 200
		}
		if (f950a1 == "lsj") {
			f950v0 = MapParser.getNewLSJJoint(f950a0, -1);
			f950v0.slen = 50;
			f950v0.sf = 5e5
		}
		if (f950a1 == "rod") {
			f950v0 = MapParser.getNewDistanceJoint(f950a0, -1);
			f950v0.d.fh = .1;
			f950v0.d.cc = false
		}
		world.physics.joints.push(f950v0);
		addBodyOptions();
		updateState(true)
	}
