	function cloneShape(shapeId, bodyId, mirror) {
		const shape = world.physics.shapes[shapeId];
		const fixture = world.physics.fixtures[shapeId];
		const shapeClone = JSON.parse(JSON.stringify(shape));
		const fixtureClone = JSON.parse(JSON.stringify(fixture));
		const clonedShapeIndex = world.physics.shapes.length;
		fixtureClone.sh = clonedShapeIndex;
		world.physics.shapes[clonedShapeIndex] = shapeClone;
		world.physics.fixtures[clonedShapeIndex] = fixtureClone;
		world.physics.bodies[bodyId].fx.push(clonedShapeIndex);
		if (mirror == "x" || mirror == "xy") {
			shapeClone.c[0] = -shapeClone.c[0]
		}
		if (mirror == "y" || mirror == "xy") {
			shapeClone.c[1] = -shapeClone.c[1]
		}
		updateState(true);
		addBodyOptions(clonedShapeIndex)
	}
