	const el_mapeditor_x_up = document.getElementById("mapeditor_x_up");
	const el_mapeditor_y_up = document.getElementById("mapeditor_y_up");
	function sliderEventValueChange() {
		const body = world.physics.bodies[bodyId];
		switch (sliderEventTarget) {
			case el_mapeditor_x_up:
				body.p[0] += 5;
				setElementValue(el_mapeditor_rightbox_table_x, body.p[0]);
				break;
			case el_mapeditor_y_up:
				body.p[1] += 5;
				setElementValue(el_mapeditor_rightbox_table_y, body.p[1]);
				break;
			case el_mapeditor_angle_up:
				body.a += 1 * rad;
				setElementValue(el_mapeditor_rightbox_table_angle, roundTo3(body.a * invRad));
				break;
			case el_mapeditor_restitution_up:
				body.s.re += .1;
				setElementValue(el_mapeditor_rightbox_table_restitution, roundTo3(body.s.re));
				break;
			case el_mapeditor_density_up:
				body.s.de += .1;
				setElementValue(el_mapeditor_rightbox_table_density, roundTo3(body.s.de));
				break;
			case el_mapeditor_friction_up:
				body.s.fric += .1;
				setElementValue(el_mapeditor_rightbox_table_friction, roundTo3(body.s.fric));
				break;
			case el_mapeditor_x_down:
				body.p[0] -= 5;
				setElementValue(el_mapeditor_rightbox_table_x, body.p[0]);
				break;
			case el_mapeditor_y_down:
				body.p[1] -= 5;
				setElementValue(el_mapeditor_rightbox_table_y, body.p[1]);
				break;
			case el_mapeditor_angle_down:
				body.a -= 1 * rad;
				setElementValue(el_mapeditor_rightbox_table_angle, roundTo3(body.a * invRad));
				break;
			case el_mapeditor_restitution_down:
				body.s.re -= .1;
				setElementValue(el_mapeditor_rightbox_table_restitution, roundTo3(body.s.re));
				break;
			case el_mapeditor_density_down:
				body.s.de -= .1;
				setElementValue(el_mapeditor_rightbox_table_density, roundTo3(body.s.de));
				break;
			case el_mapeditor_friction_down:
				body.s.fric -= .1;
				setElementValue(el_mapeditor_rightbox_table_friction, roundTo3(body.s.fric));
				break;
			case el_mapeditor_xvel_up:
				body.lv[0]++;
				setElementValue(el_mapeditor_rightbox_table_xvel, body.lv[0]);
				break;
			case el_mapeditor_yvel_up:
				body.lv[1]++;
				setElementValue(el_mapeditor_rightbox_table_yvel, body.lv[1]);
				break;
			case el_mapeditor_sspin_up:
				body.av += .1;
				setElementValue(el_mapeditor_rightbox_table_av, roundTo3(body.av));
				break;
			case el_mapeditor_ld_up:
				body.s.ld += .1;
				setElementValue(el_mapeditor_rightbox_table_ld, roundTo3(body.s.ld));
				break;
			case el_mapeditor_sd_up:
				body.s.ad += .1;
				setElementValue(el_mapeditor_rightbox_table_ad, roundTo3(body.s.ad));
				break;
			case el_mapeditor_xvel_down:
				body.lv[0]--;
				setElementValue(el_mapeditor_rightbox_table_xvel, body.lv[0]);
				break;
			case el_mapeditor_yvel_down:
				body.lv[1]--;
				setElementValue(el_mapeditor_rightbox_table_yvel, body.lv[1]);
				break;
			case el_mapeditor_sspin_down:
				body.av -= .1;
				setElementValue(el_mapeditor_rightbox_table_av, roundTo3(body.av));
				break;
			case el_mapeditor_ld_down:
				body.s.ld -= .1;
				setElementValue(el_mapeditor_rightbox_table_ld, roundTo3(body.s.ld));
				break;
			case el_mapeditor_sd_down:
				body.s.ad -= .1;
				setElementValue(el_mapeditor_rightbox_table_ad, roundTo3(body.s.ad));
				break;
			case el_mapeditor_cfx_up:
				body.cf.x += 1;
				setElementValue(el_mapeditor_rightbox_table_cfx, body.cf.x);
				break;
			case el_mapeditor_cfy_up:
				body.cf.y += 1;
				setElementValue(el_mapeditor_rightbox_table_cfy, body.cf.y);
				break;
			case el_mapeditor_cft_up:
				body.cf.ct += 1;
				setElementValue(el_mapeditor_rightbox_table_cft, body.cf.ct);
				break;
			case el_mapeditor_cfx_down:
				body.cf.x -= 1;
				setElementValue(el_mapeditor_rightbox_table_cfx, body.cf.x);
				break;
			case el_mapeditor_cfy_down:
				body.cf.y -= 1;
				setElementValue(el_mapeditor_rightbox_table_cfy, body.cf.y);
				break;
			case el_mapeditor_cft_down:
				body.cf.ct -= 1;
				setElementValue(el_mapeditor_rightbox_table_cft, body.cf.ct);
				break;
			case f845v67:
				f845v68();
				break;
			case el_mapeditor_fzx_down:
				body.fz.x -= 10;
				setElementValue(el_mapeditor_rightbox_table_forcezone_x, body.fz.x);
				break;
			case el_mapeditor_fzx_up:
				body.fz.x += 10;
				setElementValue(el_mapeditor_rightbox_table_forcezone_x, body.fz.x);
				break;
			case el_mapeditor_fzy_down:
				body.fz.y -= 10;
				setElementValue(el_mapeditor_rightbox_table_forcezone_y, body.fz.y);
				break;
			case el_mapeditor_fzy_up:
				body.fz.y += 10;
				setElementValue(el_mapeditor_rightbox_table_forcezone_y, body.fz.y);
				break;
			case el_mapeditor_forcezone_centerforce_down:
				body.fz.cf -= 10;
				body.fz.cf = Math.max(0, body.fz.cf);
				setElementValue(el_mapeditor_rightbox_table_forcezone_centerforce, body.fz.cf);
				break;
			case el_mapeditor_forcezone_centerforce_up:
				body.fz.cf += 10;
				setElementValue(el_mapeditor_rightbox_table_forcezone_centerforce, body.fz.cf);
				break
		}
		updateState(true)
	}
