	function createNewBody(shape_, cx, cy, type, noPhysics) {
		const shape = createNewShape(shape_, null, null);
		world.physics.fixtures[shape].np = noPhysics;
		const shapeBody = MapParser.getNewBody();
		shapeBody.s.fric = .5;
		shapeBody.fx[0] = shape;
		shapeBody.p[0] = cx;
		shapeBody.p[1] = cy;
		shapeBody.s.type = type;
		const bodyIndex = world.physics.bodies.length;
		world.physics.bodies[bodyIndex] = shapeBody;
		world.physics.bro.unshift(bodyIndex);
		bodyId = bodyIndex;
		spawnId = -1;
		capZoneId = -1;
		jointId = -1
	}
