	function removeShape(id) {
		for (let i = 0; i < world.physics.bodies.length; i++) {
			const body = world.physics.bodies[i];
			for (let j = 0; j < body.fx.length; j++) {
				if (body.fx[j] == id) {
					body.fx.splice(j, 1);
					j--;
					continue
				}
				if (body.fx[j] > id) {
					body.fx[j]--
				}
			}
		}
		for (let i = 0; i < world.physics.fixtures.length; i++) {
			const fixture = world.physics.fixtures[i];
			if (fixture.sh > id) {
				fixture.sh--
			}
		}
		world.physics.fixtures.splice(id, 1);
		world.physics.shapes.splice(id, 1);
		for (let i = 0; i < world.capZones.length; i++) {
			if (world.capZones[i].i == id) {
				world.capZones.splice(i, 1);
				i--
			}
		}
		for (let i = 0; i < world.capZones.length; i++) {
			if (world.capZones[i].i > id) {
				world.capZones[i].i--
			}
		}
	}
