game.getLatLngDistance = function(lat1, long1, lat2, long2, useMiles) {
	const rads = Math.PI / 180;
	lat1 *= rads;
	long1 *= rads;
	lat2 *= rads;
	long2 *= rads;
	const latDistance = lat2 - lat1;
	const longDistance = long2 - long1;
	const v1 = Math.sin(latDistance / 2) * Math.sin(latDistance / 2) + Math.cos(lat1) * Math.cos(lat2) * Math.sin(longDistance / 2) * Math.sin(longDistance / 2);
	const v2 = 2 * Math.atan2(Math.sqrt(v1), Math.sqrt(1 - v1));
	const multipliedByRadius = 6372.797 * v2;
	return Math.round(useMiles ? multipliedByRadius * .621371192 : multipliedByRadius)
};
