	this.chatStatus = chatStatus;
	function sendInputs() {
		let prevStepInputs;
		function compareInputs(a, b) {
			return a.left == b.left && a.right == b.right && a.up == b.up && a.down == b.down && a.action == b.action && a.action2 == b.action2 && a.action3 == b.action3 && a.ml == b.ml && a.mr == b.mr && a.mx == b.mx && a.my == b.my
		}
		const currentInputs = inputHandler.getInputs();
		if (!playerInputs[controlPlayerId]) {
			playerInputs[controlPlayerId] = []
		}
		function anyInputs(a) {
			return a.left || a.right || a.up || a.down || a.action || a.action2 || a.action3 || a.ml || a.mr
		}
		for (let i = currentStep - 1; i >= 0; i--) {
			if (playerInputs[controlPlayerId][i]) {
				prevStepInputs = playerInputs[controlPlayerId][i];
				break
			}
		}
		if (!prevStepInputs && anyInputs(currentInputs) || prevStepInputs && !compareInputs(currentInputs, prevStepInputs)) {
			playerInputs[controlPlayerId][currentStep] = currentInputs;
			if (room) {
				const inputs = game.encodeInputs(currentInputs);
				room.sendInputs({
					i: inputs,
					f: currentStep
				})
			}
			canvasHandler.clearAfkWarn()
		}
	}
