game.profanityCheck = function(string, badWordList) {
	string = string.toLowerCase();
	for (let i = 0; i < game.charReplacements.length; i++) {
		const replacement = game.charReplacements[i];
		string = game.stringReplaceAll(string, replacement[0], replacement[1])
	}
	for (let i = 0; i < badWordList.length; i++) {
		const badWord = badWordList[i];
		const badWordPos = string.indexOf(badWord);
		if (badWordPos != -1) {
			const endIndex = badWordPos + badWord.length;
			return {
				found: true,
				wordfound: badWord,
				findindex: badWordPos,
				continuefrom: endIndex
			}
		}
	}
	return {
		found: false
	}
};
game.sanitizeString = function(string) {
	const badWordList = game.wab;
	let foundBadWord = null;
	do {
		foundBadWord = game.profanityCheck(string, badWordList);
		if (foundBadWord.found) {
			string = game.censorString(string, foundBadWord.findindex, foundBadWord.continuefrom)
		}
	} while (foundBadWord.found);
	return string
};
game.censorString = function(string, startIndex, endIndex) {
	const preCensor = string.substr(0, startIndex);
	const postCensor = string.substr(endIndex);
	return preCensor + "bonk" + postCensor
};
game.getPageHeight = getPageHeight;
game.getPageWidth = getPageWidth;
