game.resizeGame = function() {
	let desiredWidth = getPageWidth() - 360;
	let desiredHeight = getPageHeight() - 60;
	const pageWidth = desiredWidth - 1200;
	if (pageWidth > 0) {
		desiredWidth -= pageWidth * .6
	}
	const pageHeight = desiredHeight - 750;
	if (pageHeight > 0) {
		desiredHeight -= pageHeight * .5
	}
	const aspectRatio = desiredWidth / desiredHeight;
	let newWidth = 0;
	let newHeight = 0;
	if (aspectRatio > 1.46) {
		newHeight = desiredHeight;
		newWidth = newHeight * 1.46
	} else {
		newWidth = desiredWidth;
		newHeight = newWidth / 1.46
	}
	const pageFrame = parent.document.getElementById("maingameframe");
	const pageLeftAd = parent.document.getElementById("adboxverticalleftCurse");
	const pageRightAd = parent.document.getElementById("adboxverticalCurse");
	const heightDiff_ = getPageHeight() - newHeight;
	const heightDiff = heightDiff_ / 2;
	if (heightDiff < 170) {
		const topOffset = 170 - heightDiff;
		pageFrame.style.marginTop = topOffset + "px";
		pageLeftAd.style.top = topOffset * 2 + "px";
		pageRightAd.style.top = topOffset * 2 + "px"
	} else {
		pageFrame.style.marginTop = "0px";
		pageLeftAd.style.top = "0px";
		pageRightAd.style.top = "0px"
	}
	game.zoom = 1;
	const adjustedWidth = newWidth / game.zoom - 24;
	const adjustedHeight = newHeight / game.zoom - 72;
	const el_bonkiocontainer_ = document.getElementById("bonkiocontainer");
	el_bonkiocontainer_.style.width = newWidth + "px";
	el_bonkiocontainer_.style.height = newHeight + "px";
	const el_mapeditor_ = document.getElementById("mapeditor");
	el_mapeditor_.style.maxWidth = adjustedWidth + "px";
	el_mapeditor_.style.maxHeight = adjustedHeight + "px";
	const el_maploadwindow_ = document.getElementById("maploadwindow");
	el_maploadwindow_.style.maxWidth = adjustedWidth + "px";
	el_maploadwindow_.style.maxHeight = adjustedHeight + "px";
	if (game.resizeGuide) {
		const el_mainmenuelements_ = document.getElementById("mainmenuelements");
		const el_newPlayerGuideContainer_ = document.getElementById("newPlayerGuideContainer");
		const resizeGuidePos = game.resizeGuide.target.getBoundingClientRect();
		const mainMenuPos = el_mainmenuelements_.getBoundingClientRect();
		el_newPlayerGuideContainer_.style.top = resizeGuidePos.top - mainMenuPos.top + game.resizeGuide.yOffset + "px";
		el_newPlayerGuideContainer_.style.left = resizeGuidePos.left - mainMenuPos.left + game.resizeGuide.xOffset + "px"
	}
};
